-- Annales 9e AF : textes modèles MENFP 2026 (151 questions).
-- Elles arrivent « en attente » dans la file des propositions : à valider dans l'espace admin.
-- Questions avec schéma, carte ou formule illisible dans le PDF : non reprises.
-- Relancer ce fichier n'ajoute pas de doublons.

do $$ begin
  if not exists (select 1 from public.admins) then raise exception 'Aucun compte admin trouvé'; end if;
end $$;

insert into public.submissions (author, kind, status, subject_id, payload, note)
select (select user_id from public.admins limit 1), 'question', 'pending', v.subject_id, v.payload,
       'Import annales : texte modèle MENFP 2026'
from (values
  ('sciences_exp9e', $q${"type": "qcm", "question": "Le fémur est un os :", "choices": ["de la jambe", "de la cuisse", "de l'avant-bras", "du bras"], "answer": 1, "answer_text": null, "explain": "Le fémur est l'os de la cuisse, le plus long du corps. La jambe contient le tibia et le péroné.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_exp9e', $q${"type": "qcm", "question": "La fougère est classée parmi les :", "choices": ["thallophytes", "ptéridophytes", "bryophytes", "phanérogames"], "answer": 1, "answer_text": null, "explain": "La fougère a des racines, une tige, des feuilles et des vaisseaux, mais pas de fleurs : c'est une ptéridophyte.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_exp9e', $q${"type": "qcm", "question": "L'un de ces minerais est riche en aluminium. Lequel ?", "choices": ["magnétite", "blende", "pyrite", "bauxite"], "answer": 3, "answer_text": null, "explain": "La bauxite est le minerai d'aluminium. La magnétite donne du fer, la blende du zinc, la pyrite est un sulfure de fer.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_exp9e', $q${"type": "qcm", "question": "L'enveloppe protectrice des poumons s'appelle :", "choices": ["péricarde", "plèvre", "périoste", "méninge"], "answer": 1, "answer_text": null, "explain": "La plèvre entoure les poumons. Le péricarde entoure le cœur, le périoste les os, les méninges le cerveau.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_exp9e', $q${"type": "qcm", "question": "La mousse est une cryptogame car elle est dépourvue de :", "choices": ["feuilles", "vaisseaux", "fleurs", "tige"], "answer": 2, "answer_text": null, "explain": "« Cryptogame » désigne les plantes sans fleurs (reproduction cachée). La mousse a de petites feuilles et une tige, mais aucune fleur.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_exp9e', $q${"type": "qcm", "question": "L'absorption intestinale correspond :", "choices": ["au passage des aliments du petit intestin vers le côlon", "à la progression du chyle dans le tube digestif", "au passage des nutriments de l'estomac vers le petit intestin", "au passage des nutriments du petit intestin dans le sang"], "answer": 3, "answer_text": null, "explain": "L'absorption est le passage des nutriments, à travers la paroi de l'intestin grêle (villosités), vers le sang et la lymphe.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_exp9e', $q${"type": "qcm", "question": "La présence de glucose dans l'urine est une anomalie. C'est un signe :", "choices": ["de cystite", "d'urétrite", "de diabète", "de lithiase"], "answer": 2, "answer_text": null, "explain": "Quand la glycémie est trop élevée (diabète), le rein ne retient plus tout le glucose et il passe dans l'urine (glycosurie).", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_exp9e', $q${"type": "short_answer", "question": "Dans une région où le sol est salin, on souhaite améliorer la production agricole. En cinq lignes maximum, indique quelle pratique agricole peut être mise en place.", "choices": null, "answer": null, "answer_text": "Drainer le sol et le lessiver avec de l'eau douce pour évacuer le sel, irriguer avec une eau peu salée, ajouter de la matière organique (fumier, compost) et choisir des cultures tolérantes au sel.", "explain": "Le sel empêche les racines d'absorber l'eau. Il faut donc l'éliminer (drainage, lessivage) ou cultiver des plantes qui le supportent.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_exp9e', $q${"type": "short_answer", "question": "En cinq lignes maximum, montre que la sueur régule la température du corps.", "choices": null, "answer": null, "answer_text": "Quand le corps a chaud, les glandes sudoripares produisent la sueur. En s'évaporant sur la peau, la sueur absorbe de la chaleur, ce qui refroidit le corps et maintient sa température autour de 37 °C.", "explain": "L'évaporation consomme de la chaleur : c'est le même principe qu'un vêtement mouillé qui donne froid.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_exp9e', $q${"type": "short_answer", "question": "Un patient souffre d'une anémie. Explique comment cela affecte le transport de l'oxygène dans son organisme.", "choices": null, "answer": null, "answer_text": "L'anémie est un manque de globules rouges ou d'hémoglobine. L'hémoglobine transporte l'oxygène : le sang en transporte donc moins vers les organes, ce qui provoque fatigue, essoufflement et pâleur.", "explain": "L'oxygène se fixe sur l'hémoglobine des globules rouges. Moins d'hémoglobine signifie moins d'oxygène livré aux cellules.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_exp9e', $q${"type": "essay", "question": "Entre l'augmentation de la production agricole et la protection des animaux marins, quel choix ferais-tu ? En cinq lignes maximum, argumente ta position en te basant sur les effets des engrais chimiques.", "choices": null, "answer": null, "answer_text": "Exemple : protéger les animaux marins. Les engrais chimiques en excès sont entraînés par la pluie vers les rivières et la mer. Ils provoquent une prolifération d'algues qui consomment l'oxygène de l'eau (eutrophisation) : poissons et autres animaux marins meurent. On peut produire plus en utilisant des engrais organiques et des doses raisonnables.", "explain": "Toute position est acceptée si elle s'appuie sur l'effet des engrais : pollution de l'eau, eutrophisation, mort des espèces marines.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_phys9e', $q${"type": "qcm", "question": "L'une des grandeurs physiques ci-dessous est le travail d'une force par unité de temps. Laquelle ?", "choices": ["Énergie", "Pression", "Puissance", "Travail"], "answer": 2, "answer_text": null, "explain": "La puissance est le travail fourni par seconde : P = W / t, en watts (W).", "chapter_id": null, "year": 2026, "session": "Pré-test avril 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_phys9e', $q${"type": "qcm", "question": "L'un des leviers ci-dessous est inter-résistant (du 2e genre). Lequel ?", "choices": ["Pince coupante", "Pédale d'harmonium", "Pince à glace", "Coupe-papier"], "answer": 3, "answer_text": null, "explain": "Dans un levier inter-résistant, la résistance est entre le point d'appui et la force motrice. Le coupe-papier (massicot) a son axe à une extrémité, le papier au milieu et la main à l'autre bout. La pince coupante est inter-appui, la pince à glace inter-puissante.", "chapter_id": null, "year": 2026, "session": "Pré-test avril 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_phys9e', $q${"type": "qcm", "question": "L'un des phénomènes ci-dessous impressionne le sens auditif d'un élève. Lequel ?", "choices": ["La lumière", "Le son", "L'énergie", "La chaleur"], "answer": 1, "answer_text": null, "explain": "L'oreille (sens auditif) perçoit le son. La lumière est perçue par l'œil, la chaleur par la peau.", "chapter_id": null, "year": 2026, "session": "Pré-test avril 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_phys9e', $q${"type": "qcm", "question": "La pression se calcule à l'aide de la force pressante et de la surface pressée. Quelle relation établit-elle avec la force pressante ?", "choices": ["Proportionnalité", "Proportionnalité inverse", "Égalité", "Infériorité"], "answer": 0, "answer_text": null, "explain": "P = F / S : à surface égale, si la force double, la pression double. Elle est proportionnelle à la force (et inversement proportionnelle à la surface).", "chapter_id": null, "year": 2026, "session": "Pré-test avril 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_phys9e', $q${"type": "qcm", "question": "En un lieu où g = 10 N/kg, quelle est la pression exercée par un bloc de masse 10 kg sur une surface de 400 cm² ?", "choices": ["0,25 Pa", "250 Pa", "25 Pa", "2 500 Pa"], "answer": 3, "answer_text": null, "explain": "F = m × g = 10 × 10 = 100 N. S = 400 cm² = 0,04 m². P = F / S = 100 / 0,04 = 2 500 Pa.", "chapter_id": null, "year": 2026, "session": "Pré-test avril 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_phys9e', $q${"type": "short_answer", "question": "Un sportif de masse 50 kg effectue un saut de 2 m en un lieu où g = 10 N/kg. Calcule : a) le poids de ce sportif ; b) son énergie potentielle au sommet du saut.", "choices": null, "answer": null, "answer_text": "a) P = m × g = 50 × 10 = 500 N. b) Ep = m × g × h = 50 × 10 × 2 = 1 000 J.", "explain": "Le poids s'exprime en newtons, l'énergie potentielle de pesanteur en joules (Ep = mgh).", "chapter_id": null, "year": 2026, "session": "Pré-test avril 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('maths9e', $q${"type": "qcm", "question": "Un seul des nombres suivants est le PGCD de 15 et 45. Lequel ?", "choices": ["1", "5", "15", "45"], "answer": 2, "answer_text": null, "explain": "45 = 3 × 15 : 15 divise 45 et se divise lui-même. Le plus grand diviseur commun est donc 15.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('maths9e', $q${"type": "qcm", "question": "Que vaut chaque angle d'un triangle équilatéral ?", "choices": ["45°", "60°", "90°", "120°"], "answer": 1, "answer_text": null, "explain": "Les trois angles sont égaux et leur somme vaut 180° : 180 ÷ 3 = 60°.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('maths9e', $q${"type": "qcm", "question": "Dans une série statistique, quel nom donne-t-on à la valeur qui a le plus grand effectif ?", "choices": ["Le mode", "L'étendue", "La médiane", "La moyenne"], "answer": 0, "answer_text": null, "explain": "Le mode est la valeur la plus fréquente. L'étendue est l'écart entre la plus grande et la plus petite valeur.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('maths9e', $q${"type": "qcm", "question": "Parmi les mesures suivantes, laquelle est équivalente à un hectare ?", "choices": ["100 m²", "1 000 m²", "10 000 m²", "100 000 m²"], "answer": 2, "answer_text": null, "explain": "1 ha = 1 hm² = 100 m × 100 m = 10 000 m².", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('maths9e', $q${"type": "qcm", "question": "À quel nombre correspond l'écriture 10⁴ ?", "choices": ["0,0001", "100", "1 000", "10 000"], "answer": 3, "answer_text": null, "explain": "10⁴ = 10 × 10 × 10 × 10 = 10 000 (un 1 suivi de quatre zéros).", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('maths9e', $q${"type": "qcm", "question": "GRAM est un parallélogramme dont les diagonales [GA] et [RM] se coupent en O. On donne GO = 3 cm. Quel autre segment mesure aussi 3 cm ?", "choices": ["OA", "OM", "OR", "RA"], "answer": 0, "answer_text": null, "explain": "Les diagonales d'un parallélogramme se coupent en leur milieu : O est le milieu de [GA], donc OA = GO = 3 cm.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('maths9e', $q${"type": "qcm", "question": "Dans le tableau de proportionnalité x : 3, 7, 10 et y : 12, 28, 40, quelle application linéaire lie y à x ?", "choices": ["y = 10x", "y = 7x", "y = 4x", "y = 3x"], "answer": 2, "answer_text": null, "explain": "12 ÷ 3 = 28 ÷ 7 = 40 ÷ 10 = 4. Le coefficient de proportionnalité est 4, donc y = 4x.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('maths9e', $q${"type": "qcm", "question": "Un réservoir d'eau a la forme d'un parallélépipède rectangle de 2 m de longueur, 1,5 m de largeur et 1 m de hauteur. Combien de litres d'eau peut-il contenir ?", "choices": ["30 litres", "300 litres", "3 000 litres", "3 litres"], "answer": 2, "answer_text": null, "explain": "V = 2 × 1,5 × 1 = 3 m³. Or 1 m³ = 1 000 L, donc 3 000 litres.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('maths9e', $q${"type": "short_answer", "question": "On considère un cercle de diamètre AB = 12 cm. Soit M un point du cercle tel que AM = 7 cm. Calcule la longueur de [BM].", "choices": null, "answer": null, "answer_text": "Le triangle AMB est rectangle en M (inscrit dans un demi-cercle). BM² = AB² − AM² = 144 − 49 = 95, donc BM = √95 ≈ 9,75 cm.", "explain": "Un triangle inscrit dans un cercle et dont un côté est un diamètre est rectangle : on applique ensuite le théorème de Pythagore.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('maths9e', $q${"type": "short_answer", "question": "Dans un triangle ADE, B est un point de [AD] et C un point de [AE] tels que AC = 8 cm, AB = 10 cm et AE = 12 cm. Les droites (BC) et (DE) sont parallèles. Trouve la longueur du segment [AD].", "choices": null, "answer": null, "answer_text": "D'après le théorème de Thalès : AB / AD = AC / AE, soit 10 / AD = 8 / 12. Donc AD = 10 × 12 ÷ 8 = 15 cm.", "explain": "(BC) // (DE) : les longueurs des côtés sont proportionnelles (théorème de Thalès).", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('maths9e', $q${"type": "short_answer", "question": "Un camion parcourt 450 km en 5 heures. Calcule sa vitesse moyenne en m/s.", "choices": null, "answer": null, "answer_text": "v = 450 ÷ 5 = 90 km/h. 90 km/h = 90 000 m ÷ 3 600 s = 25 m/s.", "explain": "Pour passer des km/h aux m/s, on divise par 3,6.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "L'une des batailles suivantes a occasionné la division du pays en deux États : la République de l'Ouest et le Royaume du Nord. Laquelle ?", "choices": ["La bataille de Vertières", "La bataille de la Ravine-à-Couleuvres", "La bataille de la Crête-à-Pierrot", "La bataille de Sibert"], "answer": 3, "answer_text": null, "explain": "En janvier 1807, à Sibert, Christophe affronta les troupes de Pétion. Cet affrontement consacra la scission : République au Sud et à l'Ouest (Pétion), État puis Royaume du Nord (Christophe).", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "Parmi les dates suivantes, identifie celle qui correspond à l'indépendance de Cuba.", "choices": ["20 mai 1902", "10 octobre 1868", "24 février 1895", "1er janvier 1959"], "answer": 0, "answer_text": null, "explain": "Le 20 mai 1902, Cuba devient une république indépendante après l'occupation américaine. 1868 et 1895 marquent le début de guerres d'indépendance, 1959 la révolution castriste.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "Laquelle des révolutions suivantes a eu un impact sur l'effondrement du régime colonial esclavagiste dans la Caraïbe ?", "choices": ["La Révolution anglaise", "La Révolution française", "La Révolution américaine", "La Révolution polonaise"], "answer": 1, "answer_text": null, "explain": "La Révolution française de 1789 et la Déclaration des droits de l'homme ont alimenté les luttes à Saint-Domingue, jusqu'à l'abolition de l'esclavage (1793-1794).", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "Quel président haïtien accepta en 1825 de payer la dette de l'indépendance à la France ?", "choices": ["Alexandre Pétion", "Henri Christophe", "Jean-Jacques Dessalines", "Jean-Pierre Boyer"], "answer": 3, "answer_text": null, "explain": "En 1825, Boyer accepte l'ordonnance de Charles X : 150 millions de francs en échange de la reconnaissance de l'indépendance.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "Lequel des héros indépendantistes latino-américains suivants a proclamé l'indépendance du Mexique ?", "choices": ["Agustín de Iturbide", "Bernardo O'Higgins", "José María Morelos", "Simón Bolívar"], "answer": 0, "answer_text": null, "explain": "Iturbide signe l'acte d'indépendance du Mexique en 1821. O'Higgins est lié au Chili, Bolívar au Venezuela et à la Grande-Colombie.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "Lequel des faits suivants sert d'élément déclencheur de la Seconde Guerre mondiale ?", "choices": ["Le traité de Versailles de juin 1919", "L'invasion de la Pologne par l'Allemagne le 1er septembre 1939", "La non-participation des États-Unis à la SDN", "L'occupation de la France par l'Allemagne le 22 juin 1940"], "answer": 1, "answer_text": null, "explain": "Le 1er septembre 1939, l'Allemagne envahit la Pologne ; la France et le Royaume-Uni lui déclarent la guerre le 3 septembre.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "L'une des mesures suivantes est retenue pour expliquer l'assassinat de Dessalines le 17 octobre 1806. Laquelle ?", "choices": ["Le maintien de la grande propriété", "La vérification des titres de propriété", "La distribution des terres aux généraux", "La vérification des titres de donateurs"], "answer": 1, "answer_text": null, "explain": "Dessalines voulait vérifier les titres de propriété pour récupérer les terres accaparées par les anciens libres et les généraux, ce qui lui valut leur hostilité.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "Laquelle des expressions suivantes est liée aux pays développés ?", "choices": ["Pays de la périphérie", "Pays du Nord", "Pays du Sud", "Pays du Tiers-Monde"], "answer": 1, "answer_text": null, "explain": "On oppose les pays du Nord (développés) aux pays du Sud, de la périphérie ou du Tiers-Monde (en développement).", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "L'aménagement du territoire peut se définir comme :", "choices": ["L'organisation et la gestion de l'espace d'un pays pour le bien-être de la population", "La construction de maisons dans toutes les régions d'un pays", "La division du territoire en départements administratifs", "L'exploitation des ressources naturelles sans planification"], "answer": 0, "answer_text": null, "explain": "Aménager, c'est organiser l'espace (routes, villes, équipements, zones agricoles) de façon planifiée pour améliorer la vie des habitants.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "Quel est le groupe de pays ci-dessous constitué uniquement de pays de la Caraïbe ?", "choices": ["Haïti – Venezuela – Mexique", "Haïti – Jamaïque – Trinidad", "Haïti – Mexique – Sainte-Lucie", "Haïti – Panama – Mexique"], "answer": 1, "answer_text": null, "explain": "Haïti, la Jamaïque et Trinité-et-Tobago sont des États insulaires de la Caraïbe. Le Mexique, le Venezuela et le Panama sont continentaux.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "La crise de 1929 aux États-Unis a eu des impacts à l'intérieur du pays. Laquelle des situations suivantes en est une conséquence ?", "choices": ["Le plein emploi à travers le pays", "La forte croissance économique et sociale", "Le chômage et des tensions sociales", "La stabilité et la paix totale"], "answer": 2, "answer_text": null, "explain": "Le krach boursier d'octobre 1929 entraîne faillites d'entreprises et de banques, chômage massif et misère.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "Lequel des indicateurs socio-économiques suivants désigne les pays sous-développés ?", "choices": ["Taux élevé de PIB", "Taux élevé de chômage", "Taux élevé de production", "Taux élevé de scolarisation"], "answer": 1, "answer_text": null, "explain": "Un chômage élevé est un signe de sous-développement ; un PIB, une production et une scolarisation élevés caractérisent plutôt les pays développés.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "Haïti compte 27 750 km², dont 8 000 km² aptes à la culture (selon Eddy Bastien). Quel est le pourcentage des terres cultivables d'Haïti ?", "choices": ["28,83 %", "38,8 %", "50 %", "288,3 %"], "answer": 0, "answer_text": null, "explain": "8 000 ÷ 27 750 × 100 ≈ 28,83 %.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "Parmi les couples de pays suivants, identifie celui qui faisait partie de la Triple Alliance lors de la Première Guerre mondiale.", "choices": ["Allemagne / Autriche-Hongrie", "Brésil / Canada", "Royaume-Uni / France", "Russie / Espagne"], "answer": 0, "answer_text": null, "explain": "La Triple Alliance réunissait l'Allemagne, l'Autriche-Hongrie et l'Italie. Le Royaume-Uni, la France et la Russie formaient la Triple Entente.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "qcm", "question": "Dans une localité d'Haïti, de fortes pluies provoquent des inondations et emportent la couche fertile du sol. Laquelle des actions suivantes explique le mieux cette dégradation ?", "choices": ["La coupe excessive des arbres pour fabriquer du charbon", "La pratique du reboisement dans les montagnes", "La protection des sources d'eau par les habitants", "L'aménagement de canaux d'irrigation"], "answer": 0, "answer_text": null, "explain": "Sans arbres, les racines ne retiennent plus le sol : la pluie l'emporte (érosion) et ruisselle vers les plaines (inondations).", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "short_answer", "question": "Texte : « Après l'assassinat de Jean-Jacques Dessalines en 1806, Haïti fut divisée en deux parties : le Sud dirigé par Alexandre Pétion et le Nord gouverné par Henri Christophe. Dans le Nord, Henri Christophe mit en place une administration forte et organisée. En 1811, il se proclama roi sous le nom d'Henri Ier et établit le Royaume du Nord. Il encouragea l'agriculture, développa l'éducation, fit construire des écoles, des palais comme le Palais Sans-Souci et la célèbre Citadelle Laferrière pour protéger le pays contre une éventuelle invasion française. Cependant, son régime imposait une discipline stricte aux travailleurs des plantations. »\n\nPourquoi dit-on dans le texte que Henri Christophe a mis en place dans le Nord une administration forte et organisée ?", "choices": null, "answer": null, "answer_text": "Parce qu'il a encouragé l'agriculture, développé l'éducation, construit des écoles, des palais (Sans-Souci) et la Citadelle Laferrière pour défendre le pays, tout en imposant une discipline stricte.", "explain": "La réponse doit reprendre les réalisations citées dans le texte.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "short_answer", "question": "Texte : « Après l'assassinat de Jean-Jacques Dessalines en 1806, Haïti fut divisée en deux parties : le Sud dirigé par Alexandre Pétion et le Nord gouverné par Henri Christophe. Dans le Nord, Henri Christophe mit en place une administration forte et organisée. En 1811, il se proclama roi sous le nom d'Henri Ier et établit le Royaume du Nord. Il encouragea l'agriculture, développa l'éducation, fit construire des écoles, des palais comme le Palais Sans-Souci et la célèbre Citadelle Laferrière pour protéger le pays contre une éventuelle invasion française. Cependant, son régime imposait une discipline stricte aux travailleurs des plantations. »\n\nÀ partir du texte, montre un aspect positif et un aspect négatif de l'administration de Henri Christophe.", "choices": null, "answer": null, "answer_text": "Positif : développement de l'agriculture et de l'éducation, construction d'écoles, du Palais Sans-Souci et de la Citadelle. Négatif : une discipline très stricte imposée aux travailleurs des plantations.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('sciences_sociales9e', $q${"type": "essay", "question": "Propose deux actions concrètes qui permettraient de renforcer le rôle de l'agriculture dans l'économie haïtienne et explique leurs avantages pour le pays.", "choices": null, "answer": null, "answer_text": "Exemples : 1) Construire des systèmes d'irrigation et reboiser les mornes : meilleures récoltes toute l'année, moins d'érosion. 2) Donner aux paysans du crédit, des semences et des outils modernes : production plus grande, moins d'importations, plus d'emplois et de revenus à la campagne.", "explain": "Deux actions précises, chacune avec un avantage pour le pays (production, emplois, sécurité alimentaire, exportations).", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "short_answer", "question": "Texte : « L'État a pour devoir fondamental de garantir les droits essentiels de tous les citoyens, notamment le droit à la vie, à la santé, à l'éducation et à la sécurité (articles 19 et 22 de la Constitution de 1987 amendée). En retour, le citoyen bénéficie des droits civils et politiques tels que la liberté d'expression, le droit de vote et l'égalité devant la loi. Cependant, de ces droits découlent aussi des devoirs tels que respecter les lois, payer les impôts et défendre la patrie. L'équilibre entre les droits et devoirs est essentiel pour une société juste, stable et démocratique. »\n\nIndique deux droits et deux devoirs du citoyen mentionnés dans le texte.", "choices": null, "answer": null, "answer_text": "Droits (deux parmi) : la liberté d'expression, le droit de vote, l'égalité devant la loi, le droit à la vie, à la santé, à l'éducation, à la sécurité. Devoirs (deux parmi) : respecter les lois, payer les impôts, défendre la patrie.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "short_answer", "question": "Texte : « L'État a pour devoir fondamental de garantir les droits essentiels de tous les citoyens, notamment le droit à la vie, à la santé, à l'éducation et à la sécurité (articles 19 et 22 de la Constitution de 1987 amendée). En retour, le citoyen bénéficie des droits civils et politiques tels que la liberté d'expression, le droit de vote et l'égalité devant la loi. Cependant, de ces droits découlent aussi des devoirs tels que respecter les lois, payer les impôts et défendre la patrie. L'équilibre entre les droits et devoirs est essentiel pour une société juste, stable et démocratique. »\n\nSelon le texte, pourquoi l'équilibre entre droits et devoirs est-il important ?", "choices": null, "answer": null, "answer_text": "Parce qu'il est essentiel pour avoir une société juste, stable et démocratique.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "qcm", "question": "Parmi les propositions suivantes, laquelle traduit le mieux un fondement démocratique de la nation haïtienne ?", "choices": ["La concentration des pouvoirs", "L'égalité devant la loi", "La priorité accordée à une élite", "L'exclusion de certains groupes"], "answer": 1, "answer_text": null, "explain": "En démocratie, tous les citoyens ont les mêmes droits et sont soumis aux mêmes lois.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "qcm", "question": "Parmi ces propositions, laquelle exprime le mieux l'idée des textes universels des droits humains ?", "choices": ["Les droits varient selon le pays", "Les droits sont réservés aux citoyens d'un État", "Les êtres humains ont des droits fondamentaux", "Les droits dépendent de la richesse"], "answer": 2, "answer_text": null, "explain": "La Déclaration universelle de 1948 affirme que tout être humain, partout, a des droits fondamentaux.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "qcm", "question": "La séparation des pouvoirs est un principe démocratique fondamental parce qu'elle :", "choices": ["renforce l'autorité d'un seul pouvoir", "garantit la liberté des citoyens", "réduit l'autorité des institutions", "limite la participation des citoyens"], "answer": 1, "answer_text": null, "explain": "Quand le législatif, l'exécutif et le judiciaire sont séparés, chacun contrôle les autres : on évite la dictature et on protège les libertés.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "qcm", "question": "L'une des institutions suivantes est chargée de défendre le territoire national. Laquelle ?", "choices": ["La Cour de cassation", "La Police nationale d'Haïti", "Les Forces armées d'Haïti", "La Haute Cour de justice"], "answer": 2, "answer_text": null, "explain": "Les Forces armées défendent le territoire ; la Police assure l'ordre et la sécurité publique à l'intérieur.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "qcm", "question": "Laquelle des solutions suivantes est préférable lors de la résolution d'un conflit ?", "choices": ["Satisfaire la partie qui discute le mieux", "Tenir compte des intérêts de la partie plaignante", "Tenir compte des intérêts des deux parties", "Imposer une décision arbitraire"], "answer": 2, "answer_text": null, "explain": "Une résolution pacifique et durable cherche un accord qui respecte les intérêts de chacun (négociation, médiation).", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "qcm", "question": "Parmi les propositions suivantes, laquelle respecte les principes de la justice ?", "choices": ["La police juge directement", "Le tribunal décide sans preuve", "Le suspect est puni sans jugement", "Le juge décide après analyse"], "answer": 3, "answer_text": null, "explain": "La justice suppose un jugement rendu par un juge, après examen des preuves et en respectant les droits de la défense.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "qcm", "question": "Laquelle des situations suivantes peut entraîner l'insécurité dans une communauté ?", "choices": ["La forte présence de l'État", "Le bon fonctionnement de la justice", "La faiblesse dans l'application des lois", "L'absence de population"], "answer": 2, "answer_text": null, "explain": "Quand les lois ne sont pas appliquées, les criminels ne sont pas sanctionnés : la violence et l'insécurité augmentent.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "short_answer", "question": "Associe chaque attitude à son effet. Attitudes : a) Préjugés ; b) Écoute active ; c) Agressivité ; d) Respect des différences. Effets : 1) Favorise la coexistence pacifique ; 2) Crée des divisions sociales ; 3) Permet de résoudre des conflits ; 4) Aggrave les tensions ; 5) Renforce l'amour patriotique.", "choices": null, "answer": null, "answer_text": "a-2, b-3, c-4, d-1 (l'effet 5 n'est pas utilisé).", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "short_answer", "question": "Associe chaque valeur ou obstacle à sa conséquence. a) Esprit de coopération ; b) Intolérance ; c) Inclusion ; d) Banditisme. Conséquences : 1) Déplacements forcés de population ; 2) Participation de tous ; 3) Destruction du tissu social ; 4) Développement harmonieux ; 5) Confiance envers les institutions.", "choices": null, "answer": null, "answer_text": "a-4, b-3, c-2, d-1.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "short_answer", "question": "Classe ces actions entre pouvoir législatif et pouvoir exécutif : 1) voter les lois ; 2) diriger l'administration publique ; 3) assurer la sécurité du pays ; 4) contrôler l'action du gouvernement.", "choices": null, "answer": null, "answer_text": "Pouvoir législatif : 1 (voter les lois) et 4 (contrôler l'action du gouvernement). Pouvoir exécutif : 2 (diriger l'administration publique) et 3 (assurer la sécurité du pays).", "explain": "Le Parlement fait les lois et contrôle le gouvernement ; le président et le gouvernement les exécutent et dirigent l'État.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "short_answer", "question": "Complète : L'hymne national d'Haïti est la ______. Il exprime les valeurs de ______ et de ______.", "choices": null, "answer": null, "answer_text": "La Dessalinienne. Il exprime les valeurs de patriotisme (amour de la patrie) et d'unité (on accepte aussi : liberté, travail).", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "essay", "question": "Étude de cas : dans une école, un conflit éclate entre deux groupes d'élèves à cause de moqueries. La situation dégénère en insultes et en bagarre ; certains élèves ont peur de venir à l'école. Propose deux méthodes de résolution pacifique de ce conflit.", "choices": null, "answer": null, "answer_text": "1) La médiation : un adulte ou un élève médiateur réunit les deux groupes, chacun s'exprime et ils cherchent ensemble une solution. 2) Le dialogue et la sensibilisation : séances sur le respect et les effets des moqueries, excuses mutuelles et règles de vie acceptées par tous.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('citoyennete9e', $q${"type": "essay", "question": "Étude de cas : dans un quartier, les rues sont sales à cause des déchets jetés par les habitants ; les ordures attirent les insectes et favorisent les maladies. Propose deux solutions pour améliorer durablement la gestion des déchets.", "choices": null, "answer": null, "answer_text": "1) Installer des poubelles et organiser un ramassage régulier avec la mairie. 2) Sensibiliser les habitants et lancer le tri et le recyclage (compost, plastique), avec des journées de propreté (konbit).", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "short_answer", "question": "Texte : « En Haïti, la gestion des déchets constitue un défi majeur pour les villes. Cependant, le recyclage offre des opportunités importantes. De nombreuses petites entreprises récupèrent des matériaux comme le plastique, le métal et le papier pour les transformer en nouveaux produits. Ce processus permet de réduire la pollution tout en créant des emplois. Selon le PNUE (2023), le recyclage contribue aussi à économiser les ressources naturelles et à limiter les effets du changement climatique. Toutefois, le manque d'organisation et d'infrastructures rend cette activité difficile. Pour améliorer la situation, il est nécessaire de sensibiliser la population, de renforcer les systèmes de collecte et de soutenir les initiatives locales. »\n\nQuel problème principal est évoqué dans le texte ?", "choices": null, "answer": null, "answer_text": "La gestion des déchets dans les villes d'Haïti.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "short_answer", "question": "Texte : « En Haïti, la gestion des déchets constitue un défi majeur pour les villes. Cependant, le recyclage offre des opportunités importantes. De nombreuses petites entreprises récupèrent des matériaux comme le plastique, le métal et le papier pour les transformer en nouveaux produits. Ce processus permet de réduire la pollution tout en créant des emplois. Selon le PNUE (2023), le recyclage contribue aussi à économiser les ressources naturelles et à limiter les effets du changement climatique. Toutefois, le manque d'organisation et d'infrastructures rend cette activité difficile. Pour améliorer la situation, il est nécessaire de sensibiliser la population, de renforcer les systèmes de collecte et de soutenir les initiatives locales. »\n\nQuels types de matériaux sont recyclés selon le texte ?", "choices": null, "answer": null, "answer_text": "Le plastique, le métal et le papier.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "short_answer", "question": "Texte : « En Haïti, la gestion des déchets constitue un défi majeur pour les villes. Cependant, le recyclage offre des opportunités importantes. De nombreuses petites entreprises récupèrent des matériaux comme le plastique, le métal et le papier pour les transformer en nouveaux produits. Ce processus permet de réduire la pollution tout en créant des emplois. Selon le PNUE (2023), le recyclage contribue aussi à économiser les ressources naturelles et à limiter les effets du changement climatique. Toutefois, le manque d'organisation et d'infrastructures rend cette activité difficile. Pour améliorer la situation, il est nécessaire de sensibiliser la population, de renforcer les systèmes de collecte et de soutenir les initiatives locales. »\n\nDonne deux avantages du recyclage mentionnés dans le texte.", "choices": null, "answer": null, "answer_text": "Deux parmi : il réduit la pollution, il crée des emplois, il économise les ressources naturelles, il limite les effets du changement climatique.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "short_answer", "question": "Texte : « En Haïti, la gestion des déchets constitue un défi majeur pour les villes. Cependant, le recyclage offre des opportunités importantes. De nombreuses petites entreprises récupèrent des matériaux comme le plastique, le métal et le papier pour les transformer en nouveaux produits. Ce processus permet de réduire la pollution tout en créant des emplois. Selon le PNUE (2023), le recyclage contribue aussi à économiser les ressources naturelles et à limiter les effets du changement climatique. Toutefois, le manque d'organisation et d'infrastructures rend cette activité difficile. Pour améliorer la situation, il est nécessaire de sensibiliser la population, de renforcer les systèmes de collecte et de soutenir les initiatives locales. »\n\nQuelles solutions sont proposées pour améliorer la gestion des déchets ?", "choices": null, "answer": null, "answer_text": "Sensibiliser la population, renforcer les systèmes de collecte et soutenir les initiatives locales.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "qcm", "question": "Trouve la liste qui ne contient que des outils manuels utilisés dans les métiers de la mer.", "choices": ["Senne, filet, nasse, pioche", "Nasse, canne à pêche, bateau à voile, houe", "Canot de pêche, hameçon, nasse, filet", "Bateau à moteur, treuil, GPS, carte électronique"], "answer": 2, "answer_text": null, "explain": "La pioche et la houe sont des outils agricoles ; le bateau à moteur, le treuil et le GPS ne sont pas manuels. Seule la liste c) ne contient que du matériel de pêche manuel.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "qcm", "question": "M. Pierre élève des abeilles dans son jardin à Jacmel. Il fait donc de :", "choices": ["l'apiculture", "la floriculture", "l'aviculture", "l'arboriculture"], "answer": 0, "answer_text": null, "explain": "Apiculture : élevage des abeilles. Aviculture : volailles. Floriculture : fleurs. Arboriculture : arbres.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "qcm", "question": "Parmi les sources d'énergie suivantes, laquelle est renouvelable ?", "choices": ["Pétrole", "Charbon", "Soleil", "Gaz naturel"], "answer": 2, "answer_text": null, "explain": "Le soleil ne s'épuise pas à l'échelle humaine. Pétrole, charbon et gaz naturel sont des énergies fossiles, donc épuisables.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "qcm", "question": "Le clavier d'un ordinateur est un périphérique :", "choices": ["de sortie", "d'entrée", "de stockage", "de transmission"], "answer": 1, "answer_text": null, "explain": "Le clavier fait entrer des données dans l'ordinateur. L'écran et l'imprimante sont des périphériques de sortie.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "qcm", "question": "La production en série signifie :", "choices": ["Fabriquer un seul produit sur mesure", "Fabriquer plusieurs produits identiques", "Fabriquer plusieurs produits sur commande", "Fabriquer plusieurs produits sans machines"], "answer": 1, "answer_text": null, "explain": "La production en série fabrique un grand nombre d'objets identiques, souvent à la chaîne.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "short_answer", "question": "Un pêcheur utilise un filet pour attraper des poissons. a) Explique la fonction principale du filet. b) Donne une contrainte liée à son utilisation. c) Donne la source d'énergie utilisée pour faire fonctionner le filet.", "choices": null, "answer": null, "answer_text": "a) Capturer et retenir les poissons tout en laissant passer l'eau. b) Exemple : il peut se déchirer ou s'emmêler ; il faut respecter la taille des mailles pour ne pas prendre les petits poissons. c) L'énergie humaine (musculaire) du pêcheur.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "short_answer", "question": "La famille Jean vit de l'agriculture et décide de cultiver du maïs. a) Quelles sont les principales étapes pour cultiver le maïs ? b) Pourquoi est-il important de bien entretenir le champ pendant la croissance ?", "choices": null, "answer": null, "answer_text": "a) Préparer le sol (défricher, labourer), semer, entretenir (sarcler, arroser, fertiliser, protéger contre les insectes), puis récolter et conserver. b) Pour que les mauvaises herbes et les insectes ne détruisent pas les plants : on obtient une meilleure récolte.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "short_answer", "question": "Marie doit remettre un devoir bien structuré et lisible. a) Quelles sont les étapes pour réaliser son devoir avec l'ordinateur ? b) Pourquoi est-il important d'organiser et de corriger son texte avant de le remettre ?", "choices": null, "answer": null, "answer_text": "a) Allumer l'ordinateur, ouvrir un traitement de texte, saisir le texte, le mettre en forme (titres, paragraphes), le relire et le corriger, l'enregistrer puis l'imprimer. b) Pour qu'il soit clair, sans fautes et facile à lire : le professeur comprend mieux et la note est meilleure.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "short_answer", "question": "Un élève doit représenter une houe. a) Cite deux éléments que doit contenir un dessin technique. b) Explique l'utilité du dessin technique dans la fabrication d'un objet.", "choices": null, "answer": null, "answer_text": "a) Deux parmi : les vues (face, dessus, côté), les cotes (dimensions), l'échelle, le cartouche (titre, nom, date). b) Il donne toutes les formes et dimensions exactes : on peut fabriquer l'objet sans erreur.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('etap9e', $q${"type": "short_answer", "question": "Junior André crée une entreprise de production de miel (BON MYÈL) avec 50 ouvriers et s'associe à 9 enseignants. Dépenses : salaires 100 000 HTG, fabrication des ruches 80 000 HTG, mise en bouteille et emballage 110 000 HTG, entreposage 120 000 HTG. a) Dans quel secteur d'activité se trouve cette entreprise ? b) Quelle est sa forme juridique ? c) Quelle est sa taille ? d) Calcule le coût de production. e) Le bénéfice net est de 590 000 gourdes : calcule le chiffre d'affaires. f) Donne deux avantages de travailler avec des associés.", "choices": null, "answer": null, "answer_text": "a) Le secteur primaire (apiculture). b) Une société (entreprise sociétaire : 10 associés). c) Une moyenne entreprise (50 employés). d) 100 000 + 80 000 + 110 000 + 120 000 = 410 000 HTG. e) Chiffre d'affaires = coût + bénéfice = 410 000 + 590 000 = 1 000 000 HTG. f) Plus de capital, partage des risques et des compétences.", "explain": "Chiffre d'affaires = coût de production + bénéfice.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "qcm", "question": "Le patrimoine culturel sportif désigne l'ensemble des :", "choices": ["jeux traditionnels pratiqués en Haïti", "jeux traditionnels pratiqués en Haïti et à l'étranger", "héritages liés à la pratique sportive", "objets matériels et immatériels"], "answer": 2, "answer_text": null, "explain": "Le patrimoine culturel sportif regroupe tout ce qui est hérité de la pratique sportive : jeux, règles, lieux, trophées, traditions.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "qcm", "question": "Lequel est un exemple de patrimoine sportif matériel ?", "choices": ["un slogan sportif", "une tradition orale", "un stade", "une habitude"], "answer": 2, "answer_text": null, "explain": "Un stade est un bien physique (matériel). Un slogan, une tradition orale ou une habitude sont immatériels.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "qcm", "question": "En saut, la phase où le corps quitte le sol est :", "choices": ["l'élan", "la réception", "la suspension", "l'impulsion"], "answer": 3, "answer_text": null, "explain": "Les phases du saut : élan (course), impulsion (le pied pousse et le corps quitte le sol), suspension (en l'air), réception.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "qcm", "question": "De l'Antiquité aux temps modernes, les sports de combat ont évolué pour devenir des :", "choices": ["pratiques violentes sans règles", "activités réservées uniquement aux militaires", "pratiques codifiées avec des règles de sécurité", "jeux sans contact physique"], "answer": 2, "answer_text": null, "explain": "Boxe, judo, karaté… sont aujourd'hui encadrés par des règlements, des arbitres et des protections.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "qcm", "question": "Dans un match standard de volley-ball, le nombre de joueurs par équipe sur le terrain est :", "choices": ["4 joueurs", "5 joueurs", "6 joueurs", "7 joueurs"], "answer": 2, "answer_text": null, "explain": "Chaque équipe aligne 6 joueurs sur le terrain.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "qcm", "question": "L'aérobic est une activité physique, sportive et artistique caractérisée par des :", "choices": ["mouvements lents sans musique", "exercices de force seulement", "mouvements rythmés exécutés en musique", "jeux collectifs avec ballon"], "answer": 2, "answer_text": null, "explain": "L'aérobic enchaîne des mouvements rythmés sur de la musique.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "qcm", "question": "Parmi les éléments suivants, lequel fait partie des phases fondamentales du saut ?", "choices": ["L'échauffement", "La prise d'élan", "La récupération", "L'arbitrage"], "answer": 1, "answer_text": null, "explain": "Les phases du saut sont l'élan, l'impulsion, la suspension et la réception. L'échauffement se fait avant, pas pendant le saut.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "short_answer", "question": "Texte : « Le premier match de volley-ball a eu lieu le 9 février 1896 à Holyoke. À l'origine, le jeu s'appelait le Mintonette. Le nom a été changé plus tard en volley-ball après qu'un spectateur ait suggéré que le jeu impliquait une \"volée\" de la balle d'un côté à l'autre du filet. La partie supérieure du filet se place à 2,43 mètres de hauteur pour les hommes et 2,24 mètres pour les femmes. »\n\nComplète : Le nom initial du jeu était ______, mais il a été remplacé par volley-ball en raison de la notion de ______ de la balle au-dessus du filet.", "choices": null, "answer": null, "answer_text": "Mintonette ; volée.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "short_answer", "question": "Texte : « Le premier match de volley-ball a eu lieu le 9 février 1896 à Holyoke. À l'origine, le jeu s'appelait le Mintonette. Le nom a été changé plus tard en volley-ball après qu'un spectateur ait suggéré que le jeu impliquait une \"volée\" de la balle d'un côté à l'autre du filet. La partie supérieure du filet se place à 2,43 mètres de hauteur pour les hommes et 2,24 mètres pour les femmes. »\n\nComplète : La hauteur du filet est fixée à ______ pour les hommes et à ______ pour les femmes.", "choices": null, "answer": null, "answer_text": "2,43 m pour les hommes ; 2,24 m pour les femmes.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "short_answer", "question": "Donne deux avantages ou bienfaits que la pratique de l'aérobic peut offrir.", "choices": null, "answer": null, "answer_text": "Deux parmi : améliore l'endurance et le fonctionnement du cœur et des poumons, renforce les muscles, développe la coordination et le rythme, aide à contrôler le poids, réduit le stress.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "short_answer", "question": "Complète avec le terme qui convient (atterrissage, élan, suspension, appui) : Dans un saut, ______ permet de préparer le corps, tandis que l'impulsion permet de quitter le sol.", "choices": null, "answer": null, "answer_text": "L'élan.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "short_answer", "question": "Parmi ces sports, lesquels sont des sports de combat ? Boxe, volley-ball, judo, football, taekwondo, saut, lancer, karaté.", "choices": null, "answer": null, "answer_text": "La boxe, le judo, le taekwondo et le karaté.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "essay", "question": "Lors d'un match de volley-ball, une équipe perd beaucoup de points car les joueurs renvoient directement le ballon sans organiser les trois touches (réception, passe, attaque) ; le ballon est mal contrôlé. a) Évalue les erreurs commises. b) Propose une solution.", "choices": null, "answer": null, "answer_text": "a) L'équipe ne construit pas son jeu : elle renvoie en une touche, sans réception ni passe, donc sans attaque efficace, et le ballon mal contrôlé est facile à récupérer. b) S'entraîner à la réception (manchette), à la passe (touche haute) puis à l'attaque, et communiquer pour utiliser les trois touches à chaque échange.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('eps9e', $q${"type": "essay", "question": "Un établissement expose beaucoup de trophées, mais les élèves ne connaissent pas leur signification historique. Analyse les conséquences de cette situation sur la transmission du patrimoine culturel sportif.", "choices": null, "answer": null, "answer_text": "Les élèves ne connaissent pas l'histoire sportive de leur école : le patrimoine n'est pas transmis, la fierté et l'esprit d'équipe diminuent et cette mémoire risque de disparaître. Il faudrait expliquer chaque trophée (fiches, visites, récits des anciens).", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('esthetique9e', $q${"type": "short_answer", "question": "Texte : « Le violon de campagne existe encore dans nos communautés rurales et jusqu'à l'Occupation américaine. Ici et là, dans presque toutes les régions du pays, se remarquaient d'habiles sambas ou ménestrels animant les tonnelles à l'aide du violon. Depuis l'Afrique d'ailleurs, l'esclave connaissait la banza, espèce de « violon grossier à quatre cordes et que l'on pince », en plus de ses castagnettes, de sa marimba et de ses tambours. L'adoption du violon des maîtres ne semble pas avoir eu pour objectif d'accompagner les danses populaires de l'esclave dérivant du Vaudou. Le violon était réservé aux danses imitées des colons blancs, ce qu'on nomme en langage paysan « danse bal ». » (Jean Fouchard)\n\nDe quel instrument de musique parle-t-on dans le texte ?", "choices": null, "answer": null, "answer_text": "Du violon (le violon de campagne).", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('esthetique9e', $q${"type": "short_answer", "question": "Texte : « Le violon de campagne existe encore dans nos communautés rurales et jusqu'à l'Occupation américaine. Ici et là, dans presque toutes les régions du pays, se remarquaient d'habiles sambas ou ménestrels animant les tonnelles à l'aide du violon. Depuis l'Afrique d'ailleurs, l'esclave connaissait la banza, espèce de « violon grossier à quatre cordes et que l'on pince », en plus de ses castagnettes, de sa marimba et de ses tambours. L'adoption du violon des maîtres ne semble pas avoir eu pour objectif d'accompagner les danses populaires de l'esclave dérivant du Vaudou. Le violon était réservé aux danses imitées des colons blancs, ce qu'on nomme en langage paysan « danse bal ». » (Jean Fouchard)\n\nÀ quoi servait cet instrument dont on parle dans le texte ?", "choices": null, "answer": null, "answer_text": "À animer les tonnelles et à accompagner les danses imitées des colons blancs (« danse bal »).", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('esthetique9e', $q${"type": "short_answer", "question": "Texte : « Le violon de campagne existe encore dans nos communautés rurales et jusqu'à l'Occupation américaine. Ici et là, dans presque toutes les régions du pays, se remarquaient d'habiles sambas ou ménestrels animant les tonnelles à l'aide du violon. Depuis l'Afrique d'ailleurs, l'esclave connaissait la banza, espèce de « violon grossier à quatre cordes et que l'on pince », en plus de ses castagnettes, de sa marimba et de ses tambours. L'adoption du violon des maîtres ne semble pas avoir eu pour objectif d'accompagner les danses populaires de l'esclave dérivant du Vaudou. Le violon était réservé aux danses imitées des colons blancs, ce qu'on nomme en langage paysan « danse bal ». » (Jean Fouchard)\n\nCite deux instruments que l'esclave connaissait déjà depuis l'Afrique.", "choices": null, "answer": null, "answer_text": "Deux parmi : la banza, les castagnettes, la marimba, les tambours.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('esthetique9e', $q${"type": "short_answer", "question": "Texte : « Le violon de campagne existe encore dans nos communautés rurales et jusqu'à l'Occupation américaine. Ici et là, dans presque toutes les régions du pays, se remarquaient d'habiles sambas ou ménestrels animant les tonnelles à l'aide du violon. Depuis l'Afrique d'ailleurs, l'esclave connaissait la banza, espèce de « violon grossier à quatre cordes et que l'on pince », en plus de ses castagnettes, de sa marimba et de ses tambours. L'adoption du violon des maîtres ne semble pas avoir eu pour objectif d'accompagner les danses populaires de l'esclave dérivant du Vaudou. Le violon était réservé aux danses imitées des colons blancs, ce qu'on nomme en langage paysan « danse bal ». » (Jean Fouchard)\n\nSelon l'auteur, quel était l'objectif de l'adoption du violon des maîtres par les esclaves ?", "choices": null, "answer": null, "answer_text": "Ce n'était pas d'accompagner leurs danses issues du Vaudou : le violon servait aux danses imitées des colons blancs (« danse bal »).", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('esthetique9e', $q${"type": "short_answer", "question": "Texte : « Le violon de campagne existe encore dans nos communautés rurales et jusqu'à l'Occupation américaine. Ici et là, dans presque toutes les régions du pays, se remarquaient d'habiles sambas ou ménestrels animant les tonnelles à l'aide du violon. Depuis l'Afrique d'ailleurs, l'esclave connaissait la banza, espèce de « violon grossier à quatre cordes et que l'on pince », en plus de ses castagnettes, de sa marimba et de ses tambours. L'adoption du violon des maîtres ne semble pas avoir eu pour objectif d'accompagner les danses populaires de l'esclave dérivant du Vaudou. Le violon était réservé aux danses imitées des colons blancs, ce qu'on nomme en langage paysan « danse bal ». » (Jean Fouchard)\n\nComment appelle-t-on ceux qui animaient les tonnelles à l'aide du violon ?", "choices": null, "answer": null, "answer_text": "Les sambas ou ménestrels.", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('esthetique9e', $q${"type": "qcm", "question": "Les couleurs dites primaires sont :", "choices": ["rouge, jaune, vert", "rouge, orange, bleu", "rouge, bleu, jaune", "rouge, blanc, bleu"], "answer": 2, "answer_text": null, "explain": "Rouge, bleu et jaune ne s'obtiennent par aucun mélange ; en les mélangeant, on obtient les autres couleurs.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
