  ('esthetique9e', $q${"type": "qcm", "question": "La Citadelle Laferrière a été classée par l'UNESCO au patrimoine mondial en :", "choices": ["1992", "1979", "1982", "1983"], "answer": 2, "answer_text": null, "explain": "Le Parc national historique (Citadelle, Sans-Souci, Ramiers) est inscrit au patrimoine mondial depuis 1982.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('esthetique9e', $q${"type": "short_answer", "question": "Complète : La classification du patrimoine se fait en deux grandes catégories : le ______ et le ______.", "choices": null, "answer": null, "answer_text": "Le patrimoine matériel et le patrimoine immatériel (on distingue aussi patrimoine culturel et patrimoine naturel).", "explain": null, "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
  ('esthetique9e', $q${"type": "short_answer", "question": "Associe : a) Saut-d'Eau ; b) Le konpa ; c) Bleu — avec : 1) Espérance ; 2) Symbole du calme ; 3) Patrimoine naturel ; 4) Patrimoine culturel immatériel.", "choices": null, "answer": null, "answer_text": "a-3, b-4, c-2.", "explain": "Saut-d'Eau est une chute (site naturel), le konpa une musique (immatériel), le bleu évoque le calme ; le vert symbolise l'espérance.", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
