  ('espagnol9e', $q${"type": "qcm", "question": "Texto: «Hola, me llamo Sofía. Tengo cinco años y vivo en Sevilla. Hoy es domingo y toda mi familia está en casa. Mi mamá se llama Elena. Tiene pelo negro y le gusta cocinar. Mi papá se llama Antonio. Es alto y lleva gafas. Mi hermano Carlos tiene diez años. Mi otro hermano se llama Marcos. Tiene ocho años y dibuja muy bien. Mis abuelos Ana y José vienen de Granada. Después de comer, mi abuelo José cuenta cuentos en el salón. Mi tía Laura toca la guitarra y nosotros cantamos canciones juntos. Me gusta mucho el domingo porque mi familia está junta.»\n\n¿Cuántos años tiene el hermano Marcos?", "choices": ["Cinco años", "Nueve años", "Ocho años", "Diez años"], "answer": 2, "answer_text": null, "explain": "«Marcos. Tiene ocho años.»", "chapter_id": null, "year": 2026, "session": "Texte modèle mai 2026", "source": "MENFP – Bureau national des examens d'État, texte modèle 9e AF 2026"}$q$::jsonb),
